function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
      fs.unlinkSync(repoPath);
      console.log("X " + repoPath + " FAILED to compile - not written");
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("X " + repoPath + " FAILED to compile - old copy restored");
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
function removeFile(repoPath) {
  try {
    if (!fs.existsSync(repoPath)) {
      console.log("= " + repoPath + " (already removed)");
      already++;
      return;
    }
    const backup = repoPath + BACKUP_TAG;
    if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
    fs.unlinkSync(repoPath);
    console.log("- " + repoPath + " (removed - old copy kept as " + BACKUP_TAG + ")");
    applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED to remove: " + err.message);
    warnings++;
  }
}
writeNewRepair("mobile/src/api/client.ts", "\u00a7278", false,
    "/**\n * OmniFlow Control Plane client. Every mobile screen reaches the existing\n * CP through this single typed wrapper - no direct DB access, no second\n * backend. Design goals: extremely fast (in-flight GET dedupe, sane\n * timeouts, bounded retries with jitter) and fail-soft everywhere.\n */\n\nimport { apiUrl, appVariant, appVersion } from \"@/config/env\";\nimport { logger } from \"@/lib/logger\";\n\nexport class ApiError extends Error {\n  readonly status: number;\n  readonly code: string;\n  readonly retryable: boolean;\n\n  constructor(status: number, code: string, message: string, retryable: boolean) {\n    super(message);\n    this.name = \"ApiError\";\n    this.status = status;\n    this.code = code;\n    this.retryable = retryable;\n  }\n}\n\nexport interface RequestOptions {\n  /** ms before the request is aborted (default 15000) */\n  timeoutMs?: number;\n  /** attach the bearer token (default true for /api/v1/portal routes) */\n  auth?: boolean;\n  /** extra headers */\n  headers?: Record<string, string>;\n  /** override retries for idempotent requests (default: 2 for GET) */\n  retries?: number;\n  signal?: AbortSignal;\n}\n\nexport type TokenProvider = () => Promise<{\n  access: string | null;\n  /** attempt one refresh; return the new access token or null */\n  refresh: () => Promise<string | null>;\n}>;\n\nlet tokenProvider: TokenProvider | null = null;\n\nexport function setTokenProvider(provider: TokenProvider | null): void {\n  tokenProvider = provider;\n}\n\nconst inflight = new Map<string, Promise<unknown>>();\n\nconst RETRY_STATUSES = new Set([408, 429, 500, 502, 503, 504]);\n\nfunction sleep(ms: number): Promise<void> {\n  return new Promise((r) => setTimeout(r, ms));\n}\n\nfunction jitter(ms: number): number {\n  return ms + Math.floor(Math.random() * 120);\n}\n\nasync function rawRequest<T>(\n  method: string,\n  path: string,\n  body: unknown,\n  opts: RequestOptions,\n  accessToken: string | null,\n): Promise<T> {\n  const controller = new AbortController();\n  const timeout = setTimeout(\n    () => controller.abort(),\n    opts.timeoutMs ?? 15_000,\n  );\n  const onOuterAbort = () => controller.abort();\n  opts.signal?.addEventListener(\"abort\", onOuterAbort);\n\n  const headers: Record<string, string> = {\n    Accept: \"application/json\",\n    \"X-Omniflow-Mobile\": appVersion,\n    \"X-Omniflow-App\": appVariant,\n    ...(opts.headers ?? {}),\n  };\n  if (body !== undefined) headers[\"Content-Type\"] = \"application/json\";\n  if (accessToken) headers.Authorization = `Bearer ${accessToken}`;\n\n  try {\n    const res = await fetch(`${apiUrl}${path}`, {\n      method,\n      headers,\n      body: body === undefined ? undefined : JSON.stringify(body),\n      signal: controller.signal,\n    });\n    const text = await res.text();\n    if (!res.ok) {\n      let message = res.statusText || `HTTP ${res.status}`;\n      let code = `http_${res.status}`;\n      try {\n        const parsed: unknown = JSON.parse(text);\n        if (parsed && typeof parsed === \"object\") {\n          const obj = parsed as Record<string, unknown>;\n          if (typeof obj.error === \"string\") message = obj.error;\n          if (typeof obj.message === \"string\") message = obj.message;\n          if (typeof obj.code === \"string\") code = obj.code;\n        }\n      } catch {\n        // non-JSON error body: keep the status text\n      }\n      throw new ApiError(res.status, code, message, RETRY_STATUSES.has(res.status));\n    }\n    if (!text) return undefined as T;\n    try {\n      return JSON.parse(text) as T;\n    } catch {\n      return undefined as T;\n    }\n  } catch (err) {\n    if (err instanceof ApiError) throw err;\n    const aborted =\n      (err instanceof Error && err.name === \"AbortError\") ||\n      opts.signal?.aborted === true;\n    throw new ApiError(\n      aborted ? 0 : 599,\n      aborted ? \"aborted\" : \"network\",\n      aborted ? \"Request cancelled\" : \"Network unavailable\",\n      !aborted,\n    );\n  } finally {\n    clearTimeout(timeout);\n    opts.signal?.removeEventListener(\"abort\", onOuterAbort);\n  }\n}\n\nasync function requestWithAuth<T>(\n  method: string,\n  path: string,\n  body: unknown,\n  opts: RequestOptions,\n): Promise<T> {\n  const needsAuth = opts.auth !== false && path.includes(\"/api/v1/\");\n  const provider = needsAuth ? tokenProvider : null;\n  const initial = provider ? await provider() : null;\n\n  try {\n    return await rawRequest<T>(method, path, body, opts, initial?.access ?? null);\n  } catch (err) {\n    if (err instanceof ApiError && err.status === 401 && provider && initial) {\n      const refreshed = await initial.refresh().catch(() => null);\n      if (refreshed) {\n        return rawRequest<T>(method, path, body, { ...opts, retries: 0 }, refreshed);\n      }\n    }\n    throw err;\n  }\n}\n\nasync function request<T>(\n  method: string,\n  path: string,\n  body: unknown,\n  opts: RequestOptions,\n): Promise<T> {\n  const retries = opts.retries ?? (method === \"GET\" ? 2 : 0);\n  let attempt = 0;\n  for (;;) {\n    try {\n      return await requestWithAuth<T>(method, path, body, opts);\n    } catch (err) {\n      attempt += 1;\n      const retryable = err instanceof ApiError && err.retryable;\n      if (!retryable || attempt > retries) throw err;\n      await sleep(jitter(300 * attempt));\n    }\n  }\n}\n\nfunction dedupedGet<T>(path: string, opts: RequestOptions): Promise<T> {\n  const existing = inflight.get(path);\n  if (existing) return existing as Promise<T>;\n  const p = request<T>(\"GET\", path, undefined, opts).finally(() =>\n    inflight.delete(path),\n  );\n  inflight.set(path, p);\n  return p;\n}\n\nexport const api = {\n  get<T>(path: string, opts: RequestOptions = {}): Promise<T> {\n    return dedupedGet<T>(path, opts);\n  },\n  post<T>(path: string, body?: unknown, opts: RequestOptions = {}): Promise<T> {\n    return request<T>(\"POST\", path, body, opts);\n  },\n  // \u00a7278: PUT for the portal profile document (workflows status uses POST).\n  put<T>(path: string, body?: unknown, opts: RequestOptions = {}): Promise<T> {\n    return request<T>(\"PUT\", path, body, opts);\n  },\n  patch<T>(path: string, body?: unknown, opts: RequestOptions = {}): Promise<T> {\n    return request<T>(\"PATCH\", path, body, opts);\n  },\n  delete<T>(path: string, opts: RequestOptions = {}): Promise<T> {\n    return request<T>(\"DELETE\", path, undefined, opts);\n  },\n  /** Exposed for tests and diagnostics (Home health card). */\n  _inflightCount(): number {\n    return inflight.size;\n  },\n};\n\nexport { logger as apiLogger };\n");
